const screen=document.querySelector('#screen'),nav=document.querySelector('#nav');
const names=['导图','视图','日志','AI地图','我的'];let tab=0,page='',period='月',day=12,failed=false,submitted=false;const stack=[];const draft={work:'梳理五个主页面的信息结构，完成日历与日志设计。',block:'附件接口需要确认。',plan:'整理任务详情和审批流程。',hours:'7.5'};
const head=(s,side='')=>`<header><div class="back-title">${page?'<button data-back aria-label="返回">‹</button>':''}<h2>${s}</h2></div>${side}</header>`;
const btn=(s,action,cls='primary wide')=>`<button class="${cls}" data-open="${action}">${s}</button>`;
const entry=(s,sub,action)=>`<button class="entry" data-open="${action}"><span><b>${s}</b><small>${sub}</small></span><span>›</span></button>`;
const buddy='<svg class="buddy" viewBox="0 0 90 112" aria-hidden="true"><rect x="16" y="63" width="60" height="44" rx="18" fill="#FF8A24"/><rect x="35" y="68" width="23" height="34" rx="8" fill="#FFFDF8"/><circle cx="45" cy="38" r="31" fill="#805036"/><ellipse cx="45" cy="46" rx="27" ry="23" fill="#FFE5D2"/><path d="M18 34L30 20 43 30 55 23 73 35" fill="#805036"/><circle cx="35" cy="43" r="3" fill="#3C3028"/><circle cx="56" cy="43" r="3" fill="#3C3028"/><path d="M38 53Q45 61 52 53" fill="none" stroke="#3C3028" stroke-width="2"/><rect x="55" y="84" width="29" height="22" rx="6" fill="#92C9E9"/></svg>';
const hero=(title,sub)=>`<div class="hero"><h3>${title}</h3><p class="muted">${sub}</p>${buddy}</div>`;
function open(p){stack.push({page,tab,scroll:screen.scrollTop});page=p;render();screen.scrollTop=0;}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),3000);}
function calendar(){let html=head('视图',btn('今天','today','side'))+`<div class="period"><button data-period-shift="-1" aria-label="上一周期">‹</button><h3>2026年10月</h3><button data-period-shift="1" aria-label="下一周期">›</button></div><div class="segment">${['日','周','月'].map(s=>`<button data-period="${s}" class="${s===period?'active':''}">${s}</button>`).join('')}</div><div class="legend"><span>● 任务</span><span>■ 日志</span></div>`;
if(period==='月'){html+='<div class="calendar"><div class="weekdays">'+['一','二','三','四','五','六','日'].map(s=>`<span>${s}</span>`).join('')+'</div><div class="monthgrid">';for(let i=0;i<35;i++){let d=i-2;html+=`<button data-day="${d}" class="date ${d===day?'selected':''} ${d<1||d>31?'outside':''}" aria-label="10月${d}日">${d<1?d+30:d>31?d-31:d}${[12,14,15,19,23].includes(d)?'<span class="events">任务</span>':''}</button>`;}html+='</div></div>';}
if(period==='日'){html+='<div class="time-grid"><div class="hours">';for(let h=0;h<24;h++)html+=`<div class="hour"><span>${String(h).padStart(2,'0')}:00</span>${h===14?'<button class="hour-event" data-open="task">14:00 发布素材校对 · 截止时点</button>':''}</div>`;html+='</div></div>';}
if(period==='周'){html+='<div class="week-scroll"><div class="week-head"><span></span>'+['一','二','三','四','五','六','日'].map((s,i)=>`<button data-day="${12+i}">周${s}<br>${12+i}</button>`).join('')+'</div>';for(let h=0;h<24;h++)html+=`<div class="week-line"><span>${String(h).padStart(2,'0')}:00</span>${Array.from({length:7},(_,i)=>`<div>${h===14&&i===0?'<button class="week-event" data-open="task">素材校对<br>截止14:00</button>':''}</div>`).join('')}</div>`;html+='</div>';}
html+=`<div class="agenda-title"><h3>10月${day}日 · 当天议程</h3></div>`+(day===12?entry('发布素材校对','14:00 截止 · 陈一诺','task')+entry('今天工作日志','未设时段 · 本人记录','log'): '<div class="block muted">固定演示中此日无记录。真实页面按选日查询。</div>');return html;}
function content(){const manager=document.querySelector('#role').value==='manager';if(page==='edit')return head('写日志','草稿')+`<p>2026年10月12日 · 周一</p><p class="muted">固定演示 · 输入仅保留在本页会话</p><form id="logform"><div class="document">${[['work','今日工作 *'],['block','遇到的阻碍'],['plan','明日计划']].map(([k,label])=>`<label class="field"><span>${label}</span><textarea name="${k}" ${k==='work'?'required':''}>${draft[k]}</textarea></label>`).join('')}<label class="field"><span>工时（选填，0～24）</span><input name="hours" type="number" min="0" max="24" step="0.5" value="${draft.hours}"></label></div>${failed?'<div class="alert"><strong>模拟网络失败，输入已保留</strong>可以重试，或保存演示草稿。</div>':''}<div class="sticky-action"><button type="button" id="save" class="secondary">保存草稿</button><button class="primary" type="submit">${failed?'重试提交':'提交日志'}</button></div></form>`;
if(page==='log')return head('工作日志')+`<h3>10月12日 · 林小满</h3><p class="muted">${submitted?'本次演示提交':'固定样例'} · 正式版 v1</p><div class="document">${[['今日工作',draft.work],['关联任务','发布素材校对'],['遇到的阻碍',draft.block],['明日计划',draft.plan]].map(([a,b])=>`<section><h3>${a}</h3><p>${escapeText(b)}</p></section>`).join('')}</div>`+entry('关联任务','点击打开工作对象','task')+btn('申请修订','edit');
if(page==='task')return head('任务详情')+`<div class="chips"><span class="chip blue">产品发布</span><span class="chip orange">紧急</span></div><h2>上线前验收清单</h2><div class="block section"><dl class="attributes"><dt>负责人</dt><dd>陈一诺</dd><dt>截止</dt><dd>10月14日 18:00</dd></dl></div><div class="document"><h3>工作要求</h3><p>核对发布资料、失败场景与移动端验收项，补充遗漏的说明。</p></div><h3>流转记录</h3><ol class="timeline"><li>林小满派发任务<span class="muted">10月10日 09:30</span></li><li>陈一诺接收任务<span class="muted">10月10日 10:05</span></li><li>提交成果反馈<span class="muted">10月12日 14:20</span></li></ol>`+btn(manager?'查看成果并验收':'提交成果','task-action');
if(page==='review')return head('修订审批','待处理')+`<h3>陈一诺申请修订工作日志</h3><div class="block section"><p>申请原因：补充遗漏的验收记录。</p></div><h3>修改内容</h3><div class="compare"><p class="muted">当前生效 · v1</p><p>完成页面布局与组件梳理。</p></div><div class="compare new"><p>候选版本 · v2 · 待审核</p><p>完成页面布局与组件梳理。</p><p>新增：接口失败场景验收。</p></div><h3 class="section">审核链</h3><ol class="timeline"><li>团队长 · 等待独立复核</li><li>部门复核 · 等待前级</li></ol><p class="muted">当前正式内容在全部审核通过前保持不变。</p>`+(manager?`<div class="sticky-action">${btn('驳回','reject','danger')}${btn('通过本级','approve','primary')}</div>`:'<div class="alert">员工无审核资格。</div>');
if(page==='team')return head('下属工作台')+`<div class="context">正在查看：陈一诺<br>技术部 · 移动端团队</div><div class="tabs">${['概览','资料','重点','日志','任务','AI摘要'].map((s,i)=>`<button data-category="${s}" class="${i===0?'active':''}">${s}</button>`).join('')}</div><div id="member-content">${entry('最近工作日志','仅已提交正文，草稿不展示','log')}${entry('上线前验收清单','授权范围内任务','task')}</div>`+btn('返回本人面板','self','secondary wide');
if(page==='source')return head('建议与来源')+`<h3>先确认发布依赖</h3><div class="document"><section><h3>为什么建议这样做</h3><p>验收资料仍需要汇齐，建议先核对依赖。此处是固定演示解释，不是实时评估。</p></section><section><h3>不确定性</h3><p>资料可能已更新，请打开实际来源确认。</p></section></div>`+entry('上线前验收清单','演示来源任务','task')+entry('10月12日工作日志','演示来源日志','log')+(manager?btn('编辑并人工确认任务','confirm'):'<p class="muted">无派发资格时仅保存个人建议。</p>');
if(page==='map')return head('工作关系图')+`<p class="muted">固定演示图 · 列表替代可逐条访问</p><button class="map-node wide" data-open="log">工作日志 · 来源</button><div class="map-connector">↓</div><button class="map-node map-center wide" data-open="source">目标：完成发布准备</button><div class="map-connector">↓</div><button class="map-node wide" data-open="task">行动：核对验收依赖</button>`;
if(page==='confirm')return head('人工确认')+`<div class="alert">这是建议草稿，尚未创建任务。</div><div class="document"><label class="field"><span>任务名称</span><input value="核对发布验收依赖"></label><label class="field"><span>负责人</span><select><option>陈一诺 · 授权范围样例</option></select></label><label class="field"><span>截止时间</span><input type="datetime-local" value="2026-10-14T18:00"></label></div>`+btn('确认演示创建','confirmed');
if(tab===0)return head('导图',btn('消息','notifications','side'))+hero('早上好，小满','10月12日 周一 · 从重要的事开始')+`<div class="quadrants">${[['公司重点','blue','秋季产品发布','本周客户拜访','focus'],['公司任务','orange','上线前验收清单','发布素材校对','task'],['个人重点','purple','做好前端交互','完善设计文档','focus'],['个人日志','mint','今天的草稿','10月11日工作记录','log']].map(([title,c,a,b,p])=>`<section class="quadrant ${c}"><h3>${title}</h3><button class="item" data-open="${p}"><b>${a}</b></button><button class="item" data-open="${p}"><b>${b}</b></button><button class="all" data-open="${p}">查看全部 →</button></section>`).join('')}</div>`+entry('打开今天的时间视图','查看期限与工作记录','calendar')+(manager?'<button class="fab" data-open="dispatch" aria-label="派发任务">＋</button>':'');
if(tab===1)return calendar();
if(tab===2)return head('日志',manager?btn('下属日志','team','side'):'')+`<div class="segment"><button class="active">日报</button><button data-open="report">周报</button><button data-open="report">月报</button></div><button class="chip" data-open="filter">全部日期 ⌄</button><h3 class="section">今天，慢慢写也没关系</h3>`+hero('今天的日志草稿','09:20 演示保存 · 可继续写')+btn('继续写今天日志','edit','secondary wide')+`<p class="muted section">2026年10月</p>`+[11,10,9].map(d=>`<button class="list-row" data-open="log"><span class="day"><b>${d}</b><small>10月</small></span><span><b>${d===11?'上线前验收与文档整理':'移动端组件与交互梳理'}</b><span class="muted">已提交 · 正式版 v1</span></span></button>`).join('')+`<div class="sticky-action">${btn('＋ 写今天日志','edit')}</div>`;
if(tab===3)return head('AI地图','建议草稿')+`<div class="chips"><span class="chip active">个人发展</span>${manager?'<span class="chip">团队范围</span>':''}</div>`+hero('把下一步想清楚','先看建议，再核对来源')+`<h3>今天优先处理的三件事</h3><p class="muted">固定样例 · 依据本周演示记录</p>`+['先确认发布依赖','补充接口边界说明','预留联调与缓冲时间'].map((s,i)=>`<button class="suggestion" data-open="source"><span class="number">${i+1}</span><span><b>${s}</b><small class="muted">建议需要人工判断</small><span class="source">查看演示来源 →</span></span></button>`).join('')+entry('打开工作关系图','目标、来源与行动的连接','map');
return head('我的',btn('编辑资料','profile','side'))+`<div class="block"><div class="profile"><span class="avatar">林</span><span><h3>林小满</h3><p class="muted">技术部 · 移动端团队</p></span></div><p>把复杂的工作，做得清楚一点。</p></div><h3 class="section">工作</h3><div class="menu">${[['消息中心','notifications'],['工作统计','statistics'],['审批中心','review']].map(([s,p])=>btn(s+' ›',p,'')).join('')}</div>${manager?'<h3 class="section">管理</h3><div class="menu">'+btn('下属工作台 ›','team','')+'</div>':''}<h3 class="section">通用</h3><div class="menu">${btn('设置 ›','settings','')}${btn('帮助与反馈 ›','help','')}</div>`;
}
function escapeText(s){return String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');}
function render(){const state=document.querySelector('#state').value;screen.innerHTML=page||state==='normal'?content():head(names[tab])+(state==='loading'?'<div class="skeleton"></div><div class="skeleton"></div>':`<div class="placeholder"><h3>${{empty:'当前范围暂无记录',error:'网络连接失败',forbidden:'无权访问此内容'}[state]}</h3><p class="muted">${state==='forbidden'?'未展示受保护的样例，返回其他页面或联系管理员。':'保留页面上下文，不制造业务记录。'}</p>${btn('恢复正常演示','reset')}</div>`);nav.hidden=!!page;nav.innerHTML=names.map((s,i)=>`<button data-tab="${i}" class="${tab===i?'selected':''}" aria-current="${tab===i?'page':'false'}"><span class="nav-icon">${['◇','▦','▤','✧','○'][i]}</span>${s}</button>`).join('');const form=document.querySelector('#logform');if(form){form.addEventListener('input',()=>{for(const k of Object.keys(draft))draft[k]=form.elements[k].value;});form.addEventListener('submit',e=>{e.preventDefault();if(!failed){failed=true;render();}else{submitted=true;page='log';render();toast('仅本次原型演示提交成功，未写入服务端');}});document.querySelector('#save').onclick=()=>toast('演示草稿保留在当前会话，未写入服务端');}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-tab')){tab=+b.dataset.tab;page='';stack.length=0;render();screen.scrollTop=0;}else if(b.hasAttribute('data-back')){const old=stack.pop();page=old?.page||'';tab=old?.tab??tab;render();screen.scrollTop=old?.scroll||0;}else if(b.dataset.period){period=b.dataset.period;render();}else if(b.dataset.day){day=+b.dataset.day;render();}else if(b.dataset.periodShift){toast('此原型固定10月样例；完整周期切换由Flutter实现');}else if(b.dataset.category){document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#member-content').innerHTML=b.dataset.category==='任务'?entry('上线前验收清单','授权范围内任务','task'):b.dataset.category==='日志'?entry('已提交工作日志','未提交草稿不会展示','log'):'<div class="block">'+escapeText(b.dataset.category)+' · 只读样例，不代替成员操作</div>';}else if(b.dataset.open){const p=b.dataset.open;if(p==='calendar'){tab=1;page='';render();}else if(p==='reset'){document.querySelector('#state').value='normal';render();}else if(p==='self'){page='';tab=4;render();}else if(p==='today'){day=12;render();}else if(p==='reject'){const reason=prompt('驳回必须填写原因');toast(reason?.trim()?'演示驳回，未修改正式内容':'未填写原因，未执行');}else if(p==='approve'||p==='confirmed'){toast('仅演示人工确认，未执行服务端写入');}else if(['edit','log','task','review','team','source','map','confirm'].includes(p)){open(p);}else{toast('该页布局契约已写入设计文档，当前原型未实现此操作');}}});
for(const id of ['width','scale','role','state'])document.querySelector('#'+id).addEventListener('change',()=>{document.querySelector('#phone').style.width=document.querySelector('#width').value+'px';document.documentElement.style.setProperty('--scale',document.querySelector('#scale').value);render();});render();
